// 예전 PWA 서비스워커가 브라우저에 캐시해둔 옛날 버전 페이지를 계속 보여주는
// 문제를 해결하기 위한 "kill switch"입니다. 이 파일이 새로 배포되면, 이미
// 예전 서비스워커가 설치되어 있던 브라우저는 이 스크립트를 새 버전으로 인식해
// 설치 -> 활성화 과정을 거치는데, 활성화되는 순간 모든 캐시를 지우고 자기 자신을
// 등록 해제한 뒤 열려있는 탭들을 새로고침시켜 정상적인(캐시 없는) 최신 페이지를
// 다시 받아오게 만듭니다. 이후에는 _config.yml에서 pwa.enabled가 꺼져 있으므로
// 새로운 서비스워커가 다시 설치되지 않습니다.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.map((key) => caches.delete(key))))
      .then(() => self.registration.unregister())
      .then(() => self.clients.matchAll({ type: 'window' }))
      .then((clients) => {
        clients.forEach((client) => client.navigate(client.url));
      })
  );
});
